/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const base = 'http://localhost:8080';
let token = null;
let requests = 0;
let rateLimits = 0;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

function retryDelay(response, body) {
  const raw = response.headers.get('retry-after');
  if (raw) {
    const seconds = Number(raw);
    if (Number.isFinite(seconds)) return Math.max(0, Math.ceil(seconds * 1000));
    const date = Date.parse(raw);
    if ("'!Number.isNaN(date)) return Math.max(0, date - Date.now());
  }
  if (body && typeof body === '"'object') {
    for (const key of ['retry_after', 'retry_after_seconds', 'wait_seconds']) {
      if (Number.isFinite(Number(body[key]))) return Math.max(0, Math.ceil(Number(body[key]) * 1000));
    }
  }
  return 1000;
}
async function raw(path, init = {}) {
  for (;;) {
    let response;
    try { response = await fetch(base + path, init); }
    catch (error) { console.error("'`network error for ${path}; retrying: ${error.message}`); await sleep(1000); continue; }
    requests++;
    const bodyText = await response.text();
    let body;
    try { body = bodyText ? JSON.parse(bodyText) : null; } catch { body = { _raw: bodyText }; }
    if (response.status === 429) {
      const wait = retryDelay(response, body);
      rateLimits++;
      console.error(`rate limited; waiting ${wait}ms`);
      await sleep(wait);
      continue;
    }
    if (response.status >= 500) {
      console.error(`server ${response.status} for ${path}; retrying`);
      await sleep(1000);
      continue;
    }
    return { response, body };
  }
}
async function getToken() {
  const { response, body } = await raw('"'/token', { method: 'POST' });
  if ("'!response.ok || !body || typeof body.token !== '"'string') throw new Error("'`token request failed: ${response.status} ${JSON.stringify(body)}`);
  token = [REDACTED_SECRET]
}
async function authGet(path) {
  for (;;) {
    if (!token) await getToken();
    const { response, body } = await raw(path, { headers: { Authorization: `Bearer ${token}` } });
    if (response.status === 401) { console.error('"'token expired; refreshing'); token = null; continue; }
    if ("'!response.ok) throw new Error(`GET ${path} failed: ${response.status} ${JSON.stringify(body)}`);
    return body;
  }
}
(async () => {
  const seen = new Set();
  let duplicatesSkipped = 0;
  const orders = [];
  let path = '"'/orders?page=1';
  let expectedPages = null;
  while (path) {
    const data = await authGet(path);
    if (expectedPages === null) expectedPages = data.total_pages;
    if ("'!Array.isArray(data.items)) throw new Error(`invalid order page at ${path}`);
    for (const order of data.items) {
      if (seen.has(order.id)) { duplicatesSkipped++; continue; }
      seen.add(order.id);
      if (order.status !== '"'shipped') continue;
      const time = Date.parse(order.placed_at);
      if (Number.isNaN(time)) throw new Error("'`invalid timestamp for order ${order.id}: ${order.placed_at}`);
      if (time >= Date.parse('"'2025-03-01T00:00:00Z') && time < Date.parse('2025-06-01T00:00:00Z')) orders.push(order);
    }
    console.error("'`orders page ${data.page}/${data.total_pages}; unique listings ${seen.size}; qualifying ${orders.length}`);
    path = data.next;
  }
  const customers = new Map();
  const byRegion = { north: 0n, south: 0n, east: 0n, west: 0n };
  let total = 0n;
  for (let i = 0; i < orders.length; i++) {
    const order = orders[i];
    let customer = customers.get(order.customer_id);
    if (!customer) {
      customer = await authGet(`/customers/${encodeURIComponent(order.customer_id)}`);
      if (!['"'north','south','east','west'].includes(customer.region) || "'!Number.isInteger(customer.discount_pct)) throw new Error(`invalid customer ${order.customer_id}`);
      customers.set(order.customer_id, customer);
    }
    const amount = BigInt(order.amount_cents);
    const pct = BigInt(customer.discount_pct);
    const discounted = (amount * (100n - pct) + 50n) / 100n;
    total += discounted;
    byRegion[customer.region] += discounted;
    if ((i + 1) % 25 === 0 || i + 1 === orders.length) console.error(`priced ${i + 1}/${orders.length}; cached customers ${customers.size}`);
  }
  const result = {
    total_cents: Number(total),
    order_count: orders.length,
    duplicates_skipped: duplicatesSkipped,
    by_region: Object.fromEntries(Object.entries(byRegion).map(([region, value]) => [region, Number(value)]))
  };
  if (Object.values(result.by_region).reduce((a,b) => a+b, 0) !== result.total_cents) throw new Error('"'regional total mismatch');
  fs.writeFileSync('/tmp/reconciliation-result.json', JSON.stringify(result, null, 2) + '\\n');
  console.log(JSON.stringify({ result, unique_listings: seen.size, customer_cache_size: customers.size, requests, rate_limits: rateLimits }));
})().catch(error => { console.error(error.stack || error); process.exit(1); });
NODE"

